import {
	Component,
	Event,
	EventEmitter,
	Fragment,
	Host,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { alertsWarningLarge } from "../../../icons";

let steps = [];

interface Step {
	id: string;
	path: string;
	position: number;
}

interface StepStatus {
	id: string;
	path: string;
	title: string;
	completed: boolean;
	current: boolean;
	disabled: boolean;
	number: number;
}

interface NavTree {
	children: (uuid: string) => Step[];
}

/**
 * @since 0.0.6
 * @status deprecated
 *
 */
@Component({
	tag: "hbr-workflow",
	styleUrl: "workflow.scss",
	shadow: true,
})
export class HbrWorkflows {
	@Prop() navTree: NavTree;

	@State() theme: string;

	@State() currentStep: Step;

	@State() positions: string[] = [];

	@State() nextStepId = "";

	@State() prevStepId = "";

	@State() lastStep = false;

	@State() state: object = {};

	@State() tooltipActive = false;

	@State() statusData: { stepsStatus: StepStatus[]; rate: number } = {
		stepsStatus: [],
		rate: 0,
	};

	@State() customBehavior = false;

	@State() completedSteps: string[] = [];

	@State() stepperActive = true;

	@State() saveInProgress = false;

	@State() doNotShowExitModal = false;

	@State() modalTheme = "";

	@State() workflowReady = false;

	@Event({ eventName: "hbr-launch", bubbles: true, composed: true })
	HbrLaunch: EventEmitter<object>;

	@Event({ eventName: "hbr-restart" }) HbrRestart: EventEmitter<object>;

	@Event({ eventName: "hbr-next", composed: true })
	HbrNext: EventEmitter<object>;
	private modal: HTMLHbrModalElement;
	private uuid: string;
	private childRoutes: Step[];
	private autoSave: boolean;
	private interval: NodeJS.Timeout;
	private navigate: (path: string, state: object) => void;

	@Event({ eventName: "hbr-leave" }) HbrLeave: EventEmitter<object>;

	@Event({ eventName: "hbr-complete" }) HbrExit: EventEmitter<object>;

	@Event({ eventName: "hbr-autosave" }) HbrAutoSave: EventEmitter<object>;

	@Event({ eventName: "hbr-modal-show" }) HbrModalShow: EventEmitter<boolean>;

	@Watch("modalTheme")
	handleModalTheme() {
		if (this.modalTheme.length && this.modal) {
			this.openModal();
		}
	}

	componentWillLoad() {
		if (this.navTree) {
			steps = this.navTree
				.children(this.uuid)
				.sort((a, b) => a.position - b.position);
		} else {
			console.log(this.childRoutes);
			steps = this.childRoutes.sort((a, b) => a.position - b.position);
		}
		this.positions = steps.map((a) => a.position);
		this.HbrLaunch.emit({ uuid: this.uuid, resolver: this.resolver });

		if (this.autoSave) {
			this.interval = setInterval(this.autosave, 10000);
		}
	}

	componentDidLoad() {
		if (!this.workflowReady && this.modalTheme === "resume") {
			this.openModal();
		}
	}

	disconnectedCallback() {
		this.HbrLeave.emit({ uuid: this.uuid, state: this.state });
		if (this.autoSave) {
			clearInterval(this.interval);
		}
	}

	private restartWorkflow = () => {
		this.closeModal();
		this.HbrRestart.emit({ uuid: this.uuid, resolver: this.resolver });
	};

	themeHandler = ({ activeTheme }) => {
		if (activeTheme.isCohesionV1) {
			this.theme = "cohesion";
		} else if (activeTheme.isCohesion) {
			this.theme = "cohesion";
		} else if (activeTheme.isMagnetic) {
			this.theme = "magnetic";
		}
	};

	private modalCheckboxChange = () => {
		this.HbrModalShow.emit(!this.doNotShowExitModal);
		this.doNotShowExitModal = !this.doNotShowExitModal;
	};

	private autosave = () => {
		this.saveInProgress = true;
		this.HbrAutoSave.emit({
			uuid: this.uuid,
			state: this.state,
			resolver: this.autoSaveResolver,
		});
	};

	private getStepById = (stepId) => {
		const step = steps.filter((i) => i.id === stepId);
		if (step.length > 0) {
			return step[0];
		}
		console.error(`step with "${stepId}" doesn't exist`);
	};

	private navigateToStep = (step) => {
		this.navigate(step.path, { state: this.state });
		this.currentStep = step;
		if (!this.customBehavior) {
			this.prevStepId = this.getPrevStep(this.currentStep)?.id;
			this.nextStepId = this.getNextStep(this.currentStep)?.id;
		}
	};

	private getNextStep(step) {
		const index = this.positions.indexOf(step.position) + 1;
		if (index === steps.length) {
			this.lastStep = true;
		}
		return steps[index];
	}

	private getPrevStep(step) {
		const index = this.positions.indexOf(step.position) - 1;
		if (this.lastStep) {
			this.lastStep = false;
		}
		return steps[index];
	}

	private onPrimaryClick = () => {
		const nextStep = this.getStepById(this.nextStepId);
		this.navigateToStep(nextStep);
		this.HbrNext.emit({
			uuid: this.uuid,
			state: this.state,
			stepId: this.currentStep.id,
			resolver: this.stepResolver,
		});
	};

	private onComplete = () => {
		this.HbrExit.emit({ uuid: this.uuid, state: this.state });
	};

	private onSecondaryClick = () => {
		const prevStep = this.getStepById(this.prevStepId);
		this.navigateToStep(prevStep);
		this.HbrNext.emit({
			uuid: this.uuid,
			state: this.state,
			stepId: this.currentStep.id,
			resolver: this.stepResolver,
		});
	};

	private openModal = () => {
		this.modal?.show();
	};

	private closeModal = () => {
		this.modalTheme = "";
		this.modal.hide();
	};

	private onExitClick = () => {
		this.modal.hide();
		this.HbrLeave.emit({
			uuid: this.uuid,
			state: this.state,
			customBehaviour: true,
			doNotShowExitModal: this.doNotShowExitModal,
		});
	};

	private isStepReady = (stepId) => {
		return this.completedSteps.includes(stepId);
	};

	tooltipHover = (value) => {
		this.tooltipActive = value;
	};

	getStepStatusArr = (stepId, state) => {
		const steps = [];
		let num = 0;
		let rate = 0;
		steps.forEach((it) => {
			num++;
			if (it.id === stepId) {
				rate = (num / steps.length) * 100;
			}
			steps.push({
				...it,
				completed:
					!!Object.keys(state).length && Object.keys(state).includes(it.id),
				current: it.id === stepId,
			});
		});
		return { stepsStatus: steps, rate };
	};

	resolver = ({
		state = {},
		currStepId,
		nextStepId,
		prevStepId,
		statusData,
		completedSteps = [],
		doNotShowExitModal = false,
		initialState = false,
	}) => {
		if (currStepId) {
			// custom framework behaviour
			this.nextStepId = nextStepId;
			this.prevStepId = prevStepId;
			this.navigateToStep(this.getStepById(currStepId));
			this.statusData = statusData;
			this.customBehavior = true;
			this.completedSteps = completedSteps;
		} else {
			// default framework behaviour
			let currStep = 0;
			if (state && Object.keys(state).length === 0) {
				currStep = 0;
			} else if (Object.keys(state).length === steps.length) {
				currStep = steps.length - 1;
				this.lastStep = true;
			} else {
				let i = 0;
				while (!currStep) {
					const stepId = steps[i].id;
					if (!(Object.keys(state).includes(stepId) && !!state[stepId])) {
						currStep = i;
					}
					i++;
				}
			}
			this.currentStep = steps[currStep];
			this.prevStepId = this.getPrevStep(this.currentStep)?.id;
			this.nextStepId = this.getNextStep(this.currentStep)?.id;
			this.navigateToStep(steps[currStep]);
			this.statusData = this.getStepStatusArr(steps[currStep], this.state);
			this.completedSteps = Object.keys(this.state);
			this.workflowReady = true;
		}
		if (initialState) {
			this.workflowReady = true;
		} else {
			this.modalTheme = "resume";
		}
		this.doNotShowExitModal = doNotShowExitModal;
		this.state = state;
		this.HbrNext.emit({
			uuid: this.uuid,
			state: this.state,
			stepId: this.currentStep.id,
			resolver: this.stepResolver,
		});
	};

	stepResolver = ({
		state,
		nextStepId,
		prevStepId,
		statusData,
		completedSteps,
	}) => {
		this.state = { ...this.state, ...state };
		if (this.customBehavior) {
			this.nextStepId = nextStepId;
			this.prevStepId = prevStepId;
			this.statusData = statusData;
			if (completedSteps) {
				this.completedSteps = completedSteps;
			} else {
				this.statusData = this.getStepStatusArr(this.currentStep, this.state);
				this.completedSteps = Object.keys(this.state);
			}
		}
	};

	autoSaveResolver = (success) => {
		if (success) {
			this.saveInProgress = false;
		}
	};

	toggleStepper = () => {
		this.stepperActive = !this.stepperActive;
	};

	render() {
		console.error(
			"hbr-workflow-step is deprecated in January 2025. Please use hbr-stepper instead.",
		);
		const { stepsStatus, rate } = this.statusData;
		return (
			<Host>
				{this.workflowReady ? (
					<div class={`wf-wrapper wf-wrapper-${this.theme}`}>
						{this.theme === "cohesion" && (
							<div class="wf-tooltip" part="wf-status-bar">
								<hbr-tooltip
									class="wf-tooltip-component"
									trigger="click"
									placement="bottom"
								>
									<div slot="content">
										<div class="wf-status-steps">
											{stepsStatus?.map((it, key) => (
												<div
													class={`
                            wf-status-step
                            ${
															!it.completed && !it.current
																? "wf-status-step--disabled"
																: ""
														}
                            ${it.current ? "wf-status-step--current" : ""}`}
													key={key.toString()}
													onClick={() => {
														if (it.completed) {
															this.HbrNext.emit({
																uuid: this.uuid,
																state: this.state,
																stepId: it.id,
																resolver: this.stepResolver,
															});
															this.navigateToStep(it);
														}
													}}
												>
													{it.title}
												</div>
											))}
										</div>
									</div>
									<div
										onMouseEnter={() => this.tooltipHover(true)}
										onMouseLeave={() => this.tooltipHover(false)}
										class={`wf-status-area ${
											this.tooltipActive ? "wf-status-area--active" : ""
										}`}
									>
										<div
											class={`wf-status-bar ${
												this.tooltipActive ? "wf-status-bar--active" : ""
											}`}
											style={{ width: `${rate}%` }}
										/>
									</div>
								</hbr-tooltip>
							</div>
						)}

						{this.theme === "magnetic" && (
							<div
								class={`wf-stepper ${
									this.stepperActive ? "wf-stepper_active" : ""
								}`}
							>
								{stepsStatus.map((it, key) => (
									<div
										class={"wf-stepper-item"}
										key={key.toString()}
										onClick={() => {
											if (!it.disabled) {
												this.HbrNext.emit({
													uuid: this.uuid,
													state: this.state,
													stepId: it.id,
													resolver: this.stepResolver,
												});
												this.navigateToStep(it);
											}
										}}
									>
										<hbr-workflow-step
											number={it.number}
											current={it.current}
											stepTitle={it.title}
											completed={it.completed}
											disabled={it.disabled}
											stepperActive={this.stepperActive}
										/>
									</div>
								))}
								<div class="wf-stepper-toggle" onClick={this.toggleStepper}>
									<hbr-icon
										name={`caret-${this.stepperActive ? "left" : "right"}`}
									/>
								</div>
							</div>
						)}
						<div class="wf-content-area">
							<div class="wf-user-content">
								<slot />
							</div>
							<div class="wf-control-area" part="wf-control-area">
								<div class="wf-buttons" part="wf-buttons">
									<div>
										<div part="wf-exit-button" class="wf-exit-button">
											<hbr-button
												class="hbr-fw-btn --left-margin"
												onClick={
													this.doNotShowExitModal
														? this.onExitClick
														: () => {
																this.modalTheme = "exit";
														  }
												}
												variant="text"
												size="small"
											>
												{this.theme === "magnetic" ? "Cancel" : "Exit"}
											</hbr-button>
										</div>
										{this.autoSave && (
											<div part="wf-autosave" class="wf-autosave">
												{this.saveInProgress
													? "Saving..."
													: "All changes saved"}
											</div>
										)}
									</div>
									<div class="wf-navigate-buttons" part="wf-navigate-buttons">
										{!!Object.keys(this.state).length &&
											((this.customBehavior && this.prevStepId) ||
												(!this.customBehavior &&
													!(this.currentStep.id === steps[0].id))) && (
												<div part="wf-secondary-button">
													<hbr-button
														class="hbr-fw-btn"
														onClick={this.onSecondaryClick}
														variant="outline"
														size="small"
													>
														Back
													</hbr-button>
												</div>
											)}
										{(this.isStepReady(this.currentStep.id) ||
											this.theme === "magnetic") && (
											<div part="wf-primary-button">
												<hbr-button
													class="hbr-fw-btn --left-margin --right-margin"
													onClick={
														(!this.customBehavior && !this.lastStep) ||
														(this.customBehavior && this.nextStepId)
															? this.onPrimaryClick
															: this.onComplete
													}
													variant="fill"
													size="small"
													disabled={!this.isStepReady(this.currentStep.id)}
												>
													{(!this.customBehavior && !this.lastStep) ||
													(this.customBehavior && this.nextStepId)
														? "Next"
														: "Complete"}
												</hbr-button>
											</div>
										)}
									</div>
								</div>
							</div>
						</div>
					</div>
				) : null}
				<hbr-modal
					ref={(el) => {
						this.modal = el as HTMLHbrModalElement;
						return this.modal;
					}}
					noHeader
					class="dialog-width"
				>
					<div>
						<div class="modal-title">Confirmation title</div>
						{this.modalTheme === "exit" && (
							<Fragment>
								<div class="modal-message">
									Your current progress will be saved automatically when you
									exit.
								</div>
								<div
									class="modal-checkbox"
									onHbr-click={this.modalCheckboxChange}
								>
									<hbr-checkbox>Don’t show this to me again</hbr-checkbox>
								</div>
							</Fragment>
						)}{" "}
						{this.modalTheme === "resume" && (
							<Fragment>
								<div class="modal-message">
									‘Resume’ will launch the workflow from where you last left
									off. ‘Restart’ allows you to start a new workflow.
								</div>
								<div class="modal-checkbox">
									<hbr-banner sentiment="warning" variant="fill" open>
										<hbr-icon slot="icon" asset={alertsWarningLarge} />
										'Restart' will delete all saved progress. This action can't
										be undone.
									</hbr-banner>
								</div>
							</Fragment>
						)}
					</div>
					<div slot="footer">
						<hbr-button
							class="hbr-fw-btn modal-cancel-button"
							onClick={
								this.modalTheme === "exit"
									? this.closeModal
									: this.restartWorkflow
							}
							variant="text"
							size="small"
						>
							{this.modalTheme === "exit" ? "Cancel" : "Restart"}
						</hbr-button>
						<hbr-button
							class="hbr-fw-btn"
							onClick={
								this.modalTheme === "exit"
									? this.onExitClick
									: () => {
											this.closeModal();
											this.workflowReady = true;
									  }
							}
							variant="fill"
							size="small"
						>
							{this.modalTheme === "exit" ? "Exit" : "Resume"}
						</hbr-button>
					</div>
				</hbr-modal>
			</Host>
		);
	}
}
